import sys
from collections import defaultdict

def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    V = list(map(int, data[1:N+1]))
    edges = [(int(data[N+1 + 2*i]), int(data[N+2 + 2*i])) for i in range(N-1)]

    return N, V, edges

def build_tree(edges):
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
    return tree

def is_consecutive(subset):
    subset.sort()
    return all(subset[i] + 1 == subset[i+1] for i in range(len(subset) - 1))

def count_valid_subsets(tree, V, node=1, parent=None, current_subset=None):
    if current_subset is None:
        current_subset = []

    # Add the current node's joke type to the subset
    current_subset.append(V[node-1])

    # Check if the current subset is valid
    if len(set(current_subset)) != len(current_subset):
        return 0

    if not is_consecutive(current_subset):
        return 0

    # Count this subset as valid
    count = 1

    # Recur for children
    for child in tree[node]:
        if child != parent:
            count += count_valid_subsets(tree, V, child, node, current_subset.copy())

    return count

def main():
    N, V, edges = read_input()
    tree = build_tree(edges)
    result = count_valid_subsets(tree, V)
    print(result)

if __name__ == "__main__":
    main()
